import{_ as i,C as r,o as e,c as n,a2 as a,b as d,w as s,a as l,E as c,a3 as p}from"./chunks/framework.CZqXuAiL.js";const S=JSON.parse('{"title":"S3 Database Storage for VPS","description":"Automatic PostgreSQL and MySQL/MariaDB backups to any S3-compatible storage, scheduled via systemd with retention, off-site copies, Discord alerts, and an interactive extractor.","frontmatter":{"title":"S3 Database Storage for VPS","description":"Automatic PostgreSQL and MySQL/MariaDB backups to any S3-compatible storage, scheduled via systemd with retention, off-site copies, Discord alerts, and an interactive extractor."},"headers":[],"relativePath":"s3-database-storage-for-vps/index.md","filePath":"s3-database-storage-for-vps/index.md","lastUpdated":null}'),h={name:"s3-database-storage-for-vps/index.md"};function u(g,t,b,k,m,f){const o=r("Mermaid");return e(),n("div",null,[t[1]||(t[1]=a(`<h1 id="s3-database-storage-for-vps" tabindex="-1">S3 Database Storage for VPS <a class="header-anchor" href="#s3-database-storage-for-vps" aria-label="Permalink to &quot;S3 Database Storage for VPS&quot;">​</a></h1><p>Back up your VPS databases to <strong>any S3-compatible storage</strong> — automatically, on a schedule, with retention and off-site copies.</p><h2 id="what-is-it" tabindex="-1">What is it? <a class="header-anchor" href="#what-is-it" aria-label="Permalink to &quot;What is it?&quot;">​</a></h2><p>A single interactive tool that auto-discovers the <strong>PostgreSQL</strong> and <strong>MySQL/MariaDB</strong> databases on your server, lets you pick which ones to protect, dumps them, uploads them to S3 (and keeps a copy on the node), prunes old copies, and can notify a <strong>Discord webhook</strong> on every event. A built-in <strong>extractor</strong> lets you browse and pull any backup back down.</p><p>No hand-written cron jobs, no <code>pg_dump | gzip | aws s3 cp</code> one-liners, no rotation scripts — one wizard sets up everything and systemd runs it.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>One-command interactive setup</strong> — a friendly wizard, nothing to hand-edit.</li><li><strong>Auto-discovers databases</strong> — lists every PostgreSQL and MySQL/MariaDB database; pick by number.</li><li><strong>Any S3-compatible storage</strong> — AWS S3, Cloudflare R2, Backblaze B2, Wasabi, MinIO, DigitalOcean Spaces, and more.</li><li><strong>Tidy, isolated layout</strong> — everything under a folder you name: <code>bucket/&lt;folder&gt;/&lt;db-type&gt;/&lt;db-name&gt;/&lt;timestamp&gt;.sql.gz</code>.</li><li><strong>Scheduled with systemd</strong> — hourly, every 6/12 hours, daily, weekly, or a custom expression.</li><li><strong>Retention</strong> — keep the newest <em>N</em> copies per database; the oldest is deleted automatically on S3 <strong>and</strong> locally.</li><li><strong>Off-site + on-node</strong> — uploads to S3 and also keeps a local copy.</li><li><strong>Connection test</strong> — verifies S3 before committing anything.</li><li><strong>Discord alerts (optional)</strong> — <code>trigger</code>, <code>success</code>, <code>failure</code>, and/or <code>error</code>.</li><li><strong>Interactive extractor</strong> — browse a tree of all backups, type which one you want, download it (with optional decompress).</li></ul><h2 id="quick-install" tabindex="-1">Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/AnAverageBeing/s3-database-storage-for-vps.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3-database-storage-for-vps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre></div><h2 id="quick-links" tabindex="-1">Quick Links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick Links&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/s3-database-storage-for-vps/getting-started/installation">Installation</a></li><li><a href="/pingless-studios-docs/s3-database-storage-for-vps/configuration/reference">Configuration Reference</a></li><li><a href="/pingless-studios-docs/s3-database-storage-for-vps/user-guide/cli">CLI Reference</a></li><li><a href="/pingless-studios-docs/s3-database-storage-for-vps/user-guide/extractor">The Extractor</a></li><li><a href="/pingless-studios-docs/s3-database-storage-for-vps/user-guide/webhooks">Discord Webhooks</a></li><li><a href="/pingless-studios-docs/s3-database-storage-for-vps/architecture/overview">Architecture</a></li><li><a href="https://github.com/AnAverageBeing/s3-database-storage-for-vps" target="_blank" rel="noreferrer">GitHub Repository</a></li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>`,12)),(e(),d(p,null,{default:s(()=>[c(o,{id:"mermaid-117",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5Bsystemd%20timer%5D%20--%3E%20B%5Bs3dbbackup%20backup%5D%0A%20%20%20%20B%20--%3E%20C%7BFor%20each%20database%7D%0A%20%20%20%20C%20--%3E%20D%5Bpg_dump%20%2F%20mysqldump%5D%0A%20%20%20%20D%20--%3E%20E%5Bgzip%20stream%5D%0A%20%20%20%20E%20--%3E%20F%5BUpload%20to%20S3%5D%0A%20%20%20%20E%20--%3E%20G%5BLocal%20copy%20on%20node%5D%0A%20%20%20%20F%20--%3E%20H%5BEnforce%20retention%20on%20S3%5D%0A%20%20%20%20G%20--%3E%20I%5BEnforce%20retention%20locally%5D%0A%20%20%20%20B%20--%3E%20J%5BDiscord%20webhook%5D%0A%20%20%20%20K%5Bs3dbbackup%20extract%5D%20--%3E%20L%5BBrowse%20S3%20tree%5D%0A%20%20%20%20L%20--%3E%20M%5BDownload%20%2B%20decompress%5D%0A"})]),fallback:s(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="how-it-compares" tabindex="-1">How it compares <a class="header-anchor" href="#how-it-compares" aria-label="Permalink to &quot;How it compares&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Hand-rolled cron scripts</th><th><strong>S3 Database Storage for VPS</strong></th></tr></thead><tbody><tr><td>Setup</td><td>Write scripts per database</td><td>One interactive wizard</td></tr><tr><td>Database discovery</td><td>Manual</td><td>Automatic (Postgres + MySQL/MariaDB)</td></tr><tr><td>Scheduling</td><td>crontab editing</td><td>systemd timer (chosen in the wizard)</td></tr><tr><td>Retention</td><td>Custom rotation logic</td><td>Keep newest N, auto-prune</td></tr><tr><td>Off-site + local</td><td>Two separate scripts</td><td>Both, built-in</td></tr><tr><td>Restore</td><td>Manual S3 CLI + gunzip</td><td>Interactive browse + download</td></tr><tr><td>Alerts</td><td>None</td><td>Discord webhook (trigger/success/failure/error)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use a dedicated, least-privilege S3 key scoped to the backup bucket. Credentials are stored only in <code>/etc/s3dbbackup/config.json</code> (mode <code>600</code>) and never leave your server.</p></div>',3))])}const v=i(h,[["render",u]]);export{S as __pageData,v as default};
